example.code:
sealed class RenameRoot : XmlSyntaxRewriter
{
    public override SyntaxNode? VisitElement(XmlElementSyntax node)
        => node.Name == "root" ? node.WithName("renamed") : base.VisitElement(node);
}

sealed class Counter : XmlSyntaxWalker
{
    public int Count { get; private set; }
    public override void VisitElement(XmlElementSyntax node) { Count++; base.VisitElement(node); }
}

sealed class ElementName : XmlSyntaxVisitor<string?>
{
    public override string? VisitElement(XmlElementSyntax node) => node.Name;
}

private sealed class AttributeCounter : XmlSyntaxWalker
{
    public int Count { get; private set; }
    public override void VisitAttribute(XmlAttributeSyntax node) { Count++; base.VisitAttribute(node); }
}
